begin read only;
select jsonb_build_object('functions',(select jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,pg_get_function_arguments(p.oid),pg_get_function_result(p.oid),pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig,p.proacl::text) order by p.proname) from pg_proc p where p.pronamespace='public'::regnamespace and (p.proname like 'math_%' or p.proname like 'qlm_%')),'memberships',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor),admin_option,inherit_option,set_option) order by roleid,member) from pg_auth_members where roleid in ('math_executor'::regrole,'math_extraction_worker'::regrole,'math_evaluation_worker'::regrole)),'temporary_create',has_schema_privilege('math_executor','public','CREATE'),'index',(select indexdef from pg_indexes where schemaname='public' and indexname='math_confirmed_candidate_once')) postflight;
commit;
